/**
 * Print Layout Controller
 * Consumes the 'webgis-print-state' session object generated by the main map
 * and renders a high-resolution, static layout for PDF/Image export.
 */
(() => {
  const STORAGE_KEY = 'webgis-print-state';

  // --- 1. State Management ---
  function loadPrintState() {
    try {
      const state = JSON.parse(sessionStorage.getItem(STORAGE_KEY));
      if (!state || !state.center || !Number.isFinite(state.zoom)) {
        throw new Error('Invalid or missing map state.');
      }
      return state;
    } catch (error) {
      console.error('Failed to load print state:', error);
      return null;
    }
  }

  const state = loadPrintState();
  const $ = id => document.getElementById(id);
  const statusEl = $('layoutStatus');

  if (!state) {
    statusEl.textContent = 'Map state was not found. Return to the map and choose Export as Map.';
    ['printButton', 'exportPNGButton', 'exportJPGButton', 'nativePrintButton'].forEach(id => { if ($(id)) $(id).disabled = true; });
    return;
  }

  // --- 2. Map Configuration & Initialization ---
  const BASEMAP_ATTRIBUTIONS = {
    dark: 'Basemap © CARTO · © OpenStreetMap contributors',
    satellite: 'Imagery © Esri, Maxar, Earthstar Geographics',
    bright: 'Map data © OpenStreetMap contributors · © CARTO'
  };

  function getBaseStyle(basemapMode) {
    return basemapMode === 'dark' 
      ? 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json' 
      : {
          version: 8, 
          sources: {}, 
          layers: [{ id: 'paper-background', type: 'background', paint: { 'background-color': '#e7ecee' } }]
        };
  }

  const map = new maplibregl.Map({
    container: 'printMap',
    style: getBaseStyle(state.basemap),
    center: state.center,
    zoom: state.zoom,
    bearing: state.bearing || 0,
    pitch: state.pitch || 0,
    attributionControl: true,
    preserveDrawingBuffer: true,
    interactive: true,
    renderWorldCopies: false
  });

  const insetMap = new maplibregl.Map({
    container: 'insetMap',
    style: getBaseStyle(state.basemap),
    center: state.center,
    zoom: 3,
    interactive: false,
    attributionControl: false,
    preserveDrawingBuffer: true
  });

  map.addControl(new maplibregl.ScaleControl({ maxWidth: 200, unit: 'metric' }), 'bottom-left');
  const interactionControls = [map.dragPan, map.scrollZoom, map.dragRotate, map.doubleClickZoom, map.keyboard, map.touchZoomRotate, map.touchPitch];
  function setMapAdjustmentEnabled(enabled) {
    interactionControls.forEach(control => enabled ? control?.enable() : control?.disable());
    $('adjustMapButton').setAttribute('aria-pressed', String(enabled));
    $('adjustMapButton').textContent = enabled ? 'Done adjusting' : 'Adjust map';
    $('adjustMapButton').setAttribute('aria-label', enabled ? 'Finish moving and zooming the print map' : 'Enable moving and zooming the print map');
  }
  setMapAdjustmentEnabled(false);
  let resolveMapReady;
  const mapReady = new Promise(resolve => { resolveMapReady = resolve; });
  let resolveLayersReady;
  const layersReady = new Promise(resolve => { resolveLayersReady = resolve; });

  // --- 3. UI Population ---
  function populateLayoutText() {
    const titleInput = $('layoutTitleInput');
    const authorInput = $('authorInput');

    titleInput.value = state.title || 'Map';
    $('layoutTitle').textContent = titleInput.value;
    
    titleInput.addEventListener('input', () => { 
      $('layoutTitle').textContent = titleInput.value.trim() || 'Untitled map'; 
    });
    
    authorInput.addEventListener('input', () => { 
      $('layoutAuthor').textContent = authorInput.value.trim() || '—'; 
    });

    $('layoutDate').textContent = new Intl.DateTimeFormat(undefined, { dateStyle: 'long' })
      .format(new Date(state.createdAt || Date.now()));
    
    $('attributionText').textContent = BASEMAP_ATTRIBUTIONS[state.basemap] || '';
    $('northArrow').style.transform = `rotate(${-Number(state.bearing || 0)}deg)`;
  }

  function buildLegend() {
    const legendContainer = $('legendItems');
    legendContainer.replaceChildren();

    if (!state.layers || state.layers.length === 0) {
      legendContainer.textContent = 'No active data layers';
      return;
    }

    state.layers.forEach(item => {
      const row = document.createElement('div');
      row.className = 'legend-item';
      
      const symbol = document.createElement('span');
      symbol.className = 'legend-symbol';
      symbol.style.opacity = String(item.opacity ?? 1);
      
      if (item.key === 'calculated-index' && Array.isArray(item.color)) {
        symbol.style.background = `linear-gradient(to right, ${item.color.join(', ')})`;
      } else {
        symbol.style.background = Array.isArray(item.color) ? item.color[0] : (item.color || '#3288bd');
      }

      const name = document.createElement('span');
      name.textContent = item.name;

      row.append(symbol, name);
      legendContainer.append(row);
    });
  }

  // --- 4. Layer Restoration ---
  async function restoreDataLayers() {
    const activeKeys = new Set((state.layers || []).map(layer => layer.key));

    if (state.drawnFeatures?.length) {
      map.addSource('print-drawings', { type: 'geojson', data: { type: 'FeatureCollection', features: state.drawnFeatures } });
      map.addLayer({ id: 'print-drawn-polygons', type: 'fill', source: 'print-drawings', filter: ['==', ['geometry-type'], 'Polygon'], paint: { 'fill-color': '#1aa6bb', 'fill-opacity': .28 } });
      map.addLayer({ id: 'print-drawn-lines', type: 'line', source: 'print-drawings', filter: ['==', ['geometry-type'], 'LineString'], paint: { 'line-color': '#52ff9a', 'line-width': 3 } });
      map.addLayer({ id: 'print-drawn-points', type: 'circle', source: 'print-drawings', filter: ['==', ['geometry-type'], 'Point'], paint: { 'circle-radius': 6, 'circle-color': '#52ff9a', 'circle-stroke-color': '#fff', 'circle-stroke-width': 1 } });
    }

    if (state.datasets?.length) {
      try {
        const response = await fetch('/api/datasets/');
        if (response.ok) {
          const { datasets } = await response.json();
          datasets.filter(dataset => activeKeys.has(`dataset-${dataset.id}`) && dataset.data_type === 'vektor').forEach(dataset => {
            const sourceId = `print-dataset-${dataset.id}`;
            map.addSource(sourceId, { type: 'geojson', data: { type: 'FeatureCollection', features: dataset.geojson || [] } });
            map.addLayer({ id: `${sourceId}-fill`, type: 'fill', source: sourceId, filter: ['==', ['geometry-type'], 'Polygon'], paint: { 'fill-color': '#52ff9a', 'fill-opacity': .18, 'fill-outline-color': '#52ff9a' } });
            map.addLayer({ id: `${sourceId}-line`, type: 'line', source: sourceId, filter: ['==', ['geometry-type'], 'LineString'], paint: { 'line-color': '#52ff9a', 'line-width': 2 } });
            map.addLayer({ id: `${sourceId}-points`, type: 'circle', source: sourceId, filter: ['==', ['geometry-type'], 'Point'], paint: { 'circle-radius': 5, 'circle-color': '#52ff9a' } });
          });
        }
      } catch (error) {
        console.warn('Could not restore API datasets', error);
      }
    }

    for (const item of state.rasters || []) {
      if (!activeKeys.has(item.key) || !item.dataUrl) continue;
      const image = new Image();
      image.src = item.dataUrl;
      await image.decode();
      
      const sourceId = `print-${item.key}-source`;
      map.addSource(sourceId, { 
        type: 'image', 
        url: image.src, 
        coordinates: [
          [item.bounds[0], item.bounds[3]], 
          [item.bounds[2], item.bounds[3]], 
          [item.bounds[2], item.bounds[1]], 
          [item.bounds[0], item.bounds[1]]
        ] 
      });
      map.addLayer({ 
        id: `print-${item.key}-layer`, 
        type: 'raster', 
        source: sourceId, 
        paint: { 'raster-opacity': item.opacity ?? 1 } 
      });
    }

    const targetLayer = map.getStyle().layers?.find(layer => layer.type === 'symbol')?.id;
    if (state.basemap === 'satellite') {
      map.addSource('print-satellite', { type: 'raster', tiles: ['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'], tileSize: 256 });
      map.addLayer({ id: 'print-satellite-layer', type: 'raster', source: 'print-satellite' }, targetLayer);
    } else if (state.basemap === 'bright') {
      map.addSource('print-voyager', { type: 'raster', tiles: ['/tiles/carto-voyager/voyager/{z}/{x}/{y}.png'], tileSize: 256 });
      map.addLayer({ id: 'print-voyager-layer', type: 'raster', source: 'print-voyager' }, targetLayer);
    }
  }

  // --- 5. Cartographic Grids & Overlays ---
  function renderCoordinateGrid() {
    if (!map.isStyleLoaded()) return;
    const gridToggle = $('gridToggle');
    const bounds = map.getBounds();
    const [west, south, east, north] = [bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()];
    
    const rawStep = Math.max(0.01, Math.max(east - west, north - south) / 5);
    const magnitude = 10 ** Math.floor(Math.log10(rawStep));
    const step = [1, 2, 5, 10].map(v => v * magnitude).find(v => v >= rawStep) || 10 * magnitude;
    
    const features = [];
    for (let lon = Math.ceil(west / step) * step; lon <= east; lon += step) {
      features.push({ type: 'Feature', geometry: { type: 'LineString', coordinates: [[lon, south], [lon, north]] } });
    }
    for (let lat = Math.ceil(south / step) * step; lat <= north; lat += step) {
      features.push({ type: 'Feature', geometry: { type: 'LineString', coordinates: [[west, lat], [east, lat]] } });
    }

    if (map.getLayer('print-grid-lines')) map.removeLayer('print-grid-lines');
    if (map.getSource('print-grid')) map.removeSource('print-grid');
    
    map.addSource('print-grid', { type: 'geojson', data: { type: 'FeatureCollection', features } });
    map.addLayer({ 
      id: 'print-grid-lines', 
      type: 'line', 
      source: 'print-grid', 
      layout: { visibility: gridToggle.checked ? 'visible' : 'none' }, 
      paint: { 'line-color': '#233c45', 'line-width': 0.5, 'line-opacity': 0.25, 'line-dasharray': [2, 4] } 
    });

    $('gridTop').textContent = `Longitude ${((west + east) / 2).toFixed(3)}° · grid ${step.toPrecision(1)}°`;
    $('gridBottom').textContent = `Latitude ${((south + north) / 2).toFixed(3)}°`;
  }

  function updateInsetExtent() {
    const b = map.getBounds();
    if (insetMap.getSource('print-extent')) insetMap.removeSource('print-extent');
    if (insetMap.getLayer('print-extent-fill')) insetMap.removeLayer('print-extent-fill');
    if (insetMap.getLayer('print-extent-line')) insetMap.removeLayer('print-extent-line');
    
    insetMap.addSource('print-extent', { 
      type: 'geojson', 
      data: { type: 'Feature', geometry: { type: 'Polygon', coordinates: [[[b.getWest(), b.getSouth()], [b.getEast(), b.getSouth()], [b.getEast(), b.getNorth()], [b.getWest(), b.getNorth()], [b.getWest(), b.getSouth()]]] } } 
    });
    insetMap.addLayer({ id: 'print-extent-fill', type: 'fill', source: 'print-extent', paint: { 'fill-color': '#da4838', 'fill-opacity': 0.12 } });
    insetMap.addLayer({ id: 'print-extent-line', type: 'line', source: 'print-extent', paint: { 'line-color': '#d5392d', 'line-width': 2 } });
  }

  function updateMapMetrics() {
    const latitude = map.getCenter().lat;
    const metersPerPixel = 156543.03392 * Math.cos(latitude * Math.PI / 180) / (2 ** map.getZoom());
    const frameMeters = metersPerPixel * $('printMap').clientWidth;
    const frameOnPaperMeters = parseFloat(getComputedStyle($('paper')).width) / 3779.5276;
    
    $('zoomText').textContent = `Zoom: ${map.getZoom().toFixed(2)} · Approx. scale 1:${Math.max(1, Math.round(frameMeters / frameOnPaperMeters)).toLocaleString()}`;
    $('centerText').textContent = `Center: ${map.getCenter().lat.toFixed(5)}° N, ${map.getCenter().lng.toFixed(5)}° E`;
    
    const bounds = map.getBounds();
    $('extentText').textContent = `Extent: ${[bounds.getWest(), bounds.getSouth(), bounds.getEast(), bounds.getNorth()].map(v => v.toFixed(3)).join(', ')}`;
  }

  // --- 6. Export Capabilities ---
  async function captureMapSnapshot() {
    const waitUntilReady = promise => Promise.race([
      promise,
      new Promise((_, reject) => setTimeout(() => reject(new Error('The print map did not finish loading. Reload the layout and try again.')), 20000))
    ]);
    await waitUntilReady(mapReady);
    await waitUntilReady(layersReady);
    map.resize();

    if (!map.loaded() || !map.areTilesLoaded()) {
      await new Promise((resolve, reject) => {
        function onMapIdle() {
          clearTimeout(timeout);
          resolve();
        }

        const timeout = setTimeout(() => {
          map.off('idle', onMapIdle);
          reject(new Error('The map is still loading. Wait for it to finish, then export again.'));
        }, 15000);

        map.once('idle', onMapIdle);
      });
    }

    await new Promise(resolve => {
      requestAnimationFrame(() => requestAnimationFrame(resolve));
      setTimeout(resolve, 100);
    });

    const canvas = map.getCanvas();
    let snapshot = $('printSnapshot');
    
    if (!snapshot) {
      snapshot = document.createElement('img');
      snapshot.id = 'printSnapshot';
      snapshot.style.position = 'absolute';
      snapshot.style.top = '0';
      snapshot.style.left = '0';
      snapshot.style.width = '100%';
      snapshot.style.height = '100%';
      snapshot.style.zIndex = '1';
      
      $('printMap').append(snapshot);
    }
    
    snapshot.src = canvas.toDataURL('image/png');
    await snapshot.decode();
    canvas.style.visibility = 'hidden';
  }

  async function preparePrintCanvas() {
    statusEl.textContent = 'Preparing map canvas for export...';
    if (!window.html2canvas) {
      throw new Error('The layout export library (html2canvas) did not load. Check your connection and reload.');
    }
    await captureMapSnapshot();

    return window.html2canvas($('paper'), { 
      scale: 2, 
      useCORS: true, 
      backgroundColor: '#ffffff', 
      logging: false 
    });
  }

  async function exportDocument(type) {
    const isPDF = type === 'pdf';
    statusEl.textContent = 'Generating file...';
    
    try {
      if (isPDF && !window.jspdf?.jsPDF) {
        throw new Error('The PDF export library did not load. Check your connection and reload.');
      }
      const renderedCanvas = await preparePrintCanvas();
      
      if (isPDF) {
        const landscape = $('paper').classList.contains('a4-landscape');
        const pdf = new window.jspdf.jsPDF({ orientation: landscape ? 'landscape' : 'portrait', unit: 'mm', format: 'a4', compress: true });
        pdf.addImage(renderedCanvas.toDataURL('image/jpeg', 0.94), 'JPEG', 0, 0, landscape ? 297 : 210, landscape ? 210 : 297, undefined, 'FAST');
        pdf.save(`webgis-map-layout-${new Date().toISOString().slice(0, 10)}.pdf`);
      } else {
        const mime = type === 'jpg' ? 'image/jpeg' : 'image/png';
        const link = document.createElement('a');
        link.href = renderedCanvas.toDataURL(mime, type === 'jpg' ? 0.94 : undefined);
        link.download = `webgis-map-layout-${new Date().toISOString().slice(0, 10)}.${type}`;
        link.click();
      }
      statusEl.textContent = '';
    } catch (error) {
      statusEl.textContent = `Export failed: ${error.message}`;
    } finally {
      map.getCanvas().style.visibility = '';
      if ($('printSnapshot'))$('printSnapshot').remove();
      map.resize();
    }
  }

  function setOrientation(orientation) {
    const isLandscape = orientation === 'landscape';
    const bounds = map.getBounds();
    $('paper').classList.toggle('a4-landscape', isLandscape);$('paper').classList.toggle('a4-portrait', !isLandscape);
    $('portraitButton').setAttribute('aria-pressed', String(!isLandscape));$('landscapeButton').setAttribute('aria-pressed', String(isLandscape));
    
    map.resize(); 
    insetMap.resize();
    
    if (map.loaded()) map.fitBounds(bounds, { padding: 0, animate: false });
    updateMapMetrics();
  }

  // --- 7. Event Binding & Bootstrapping ---
  $('portraitButton').addEventListener('click', () => setOrientation('portrait'));$('landscapeButton').addEventListener('click', () => setOrientation('landscape'));
  $('adjustMapButton').addEventListener('click', () => setMapAdjustmentEnabled($('adjustMapButton').getAttribute('aria-pressed') !== 'true'));
  $('printButton').addEventListener('click', () => exportDocument('pdf'));$('exportPNGButton').addEventListener('click', () => exportDocument('png'));
  $('exportJPGButton').addEventListener('click', () => exportDocument('jpg'));$('gridToggle').addEventListener('change', (e) => {
    if (map.getLayer('print-grid-lines')) {
      map.setLayoutProperty('print-grid-lines', 'visibility', e.target.checked ? 'visible' : 'none');
    }
  });
  $('nativePrintButton').addEventListener('click', async event => {
    const button = event.currentTarget;
    button.disabled = true;
    statusEl.textContent = 'Preparing map for printing...';
    try {
      await captureMapSnapshot();
      statusEl.textContent = '';
      window.print();
    } catch (error) {
      statusEl.textContent = `Print preparation failed: ${error.message}`;
    } finally {
      button.disabled = false;
    }
  });
  window.addEventListener('afterprint', () => {
    map.getCanvas().style.visibility = '';
    if ($('printSnapshot')) $('printSnapshot').remove();
    map.resize();
  });

  map.on('moveend', () => {
    renderCoordinateGrid();
    
    // Prevent race condition when moving map
    if (insetMap.loaded()) {
      updateInsetExtent();
    }
    updateMapMetrics();
  });

  map.once('load', async () => {
    resolveMapReady();
    populateLayoutText();
    buildLegend();

    if (state.labels === false) {
      const layers = map.getStyle().layers;
      if (layers) {
        layers.filter(l => l.type === 'symbol').forEach(l => map.setLayoutProperty(l.id, 'visibility', 'none'));
      }
    }
    
    if (Array.isArray(state.bbox) && state.bbox.length === 4) {
      map.fitBounds([[state.bbox[0], state.bbox[1]], [state.bbox[2], state.bbox[3]]], { padding: 0, animate: false });
    }

    try {
      await restoreDataLayers();
      renderCoordinateGrid();
      
      // FIXED: Ensure inset map is fully loaded before drawing extent polygon
      if (insetMap.loaded()) {
        updateInsetExtent();
      } else {
        insetMap.once('load', updateInsetExtent);
      }
    } catch (error) {
      statusEl.textContent = 'Warning: Some map layers failed to load.';
    } finally {
      resolveLayersReady();
    }
  });

  setOrientation('portrait');
})();
